#include <bits/stdc++.h>
using namespace std;
class Solution {public:int longestEqualSubarray(vector<int>& nums,int k){unordered_map<int,vector<int>> pos;for(int i=0;i<(int)nums.size();++i)pos[nums[i]].push_back(i);int ans=0;for(auto &kv:pos){auto &v=kv.second;int l=0;for(int r=0;r<(int)v.size();++r){while(v[r]-v[l]-(r-l)>k)++l;ans=max(ans,r-l+1);}}return ans;}};
